local G = {{"dark", "lab-dark-2", 0}, {"white", "lab-white", 600}}
for _, g in ipairs(G) do local p = {g[3] + 0, 0}; build[#build + 1] = {name = "lp-player-dome", force = "player", pos = p, ground = g[2], ground_r = 11}; shots[#shots + 1] = {name = "lp-player-dome-" .. g[1], tick = t, pos = {p[1], p[2] - 0.45}, zoom = 5.29, daytime = 0, hide_clouds = true}; t = t + 2 end
